2写的c#代码
`    internal abstract class ScriptTaskBase : IScriptTask
    {
        public abstract string Name { get; }
        public virtual float CheckIntervalSeconds =&gt; 1f;
        public virtual int Priority =&gt; 100;
        public virtual string MutexGroup =&gt; null;
        public virtual float TimeoutSeconds =&gt; 30f;

        public abstract bool CanExecute();
        public abstract IEnumerator Execute();

        protected static bool CanScriptRun(bool isRun = true) =&gt; ComponentBase.CanScriptRun(isRun);
        protected static bool IsShopScene() =&gt; ComponentBase.IsShopScene();
        protected static bool IsAnyDialogActive() =&gt; ComponentBase.IsAnyDialogActive();
        protected static bool CanPerformOperation() =&gt; ComponentBase.CanPerformOperation();
        protected static bool IsSimUnlocked() =&gt; ComponentBase.IsSimUnlocked();
        protected static User GetUser() =&gt; ComponentBase.GetUser();
        protected static City GetCity() =&gt; ComponentBase.GetCity();
        protected static SimulationContext GetCurrentSimContext() =&gt; ComponentBase.GetCurrentSimContext();
        protected static void UnlockSimulationLock(string reason = "") =&gt; ComponentBase.UnlockSimulationLock(reason);
        protected static void LockSimulationLock(string reason = "") =&gt; ComponentBase.LockSimulationLock(reason);
        protected static void SendUserAction(string actionName, Dict parameters = null) =&gt; ComponentBase.SendUserAction(actionName, parameters);
        protected static void SendChatMessage(string message, ChatManager.Channel channel = ChatManager.Channel.World) =&gt; ComponentBase.SendChatMessage(message, channel);
        protected static void PushMessage(string msg, int type = 0) =&gt; ComponentBase.PushMessage(msg, type);
        protected static void LogInfo(string msg) =&gt; ComponentBase.LogInfo(msg);
        protected static void LogWarning(string msg) =&gt; ComponentBase.LogWarning(msg);
        protected static void LogError(string msg) =&gt; ComponentBase.LogError(msg);
        protected static void LogDebug(string msg) =&gt; ComponentBase.LogDebug(msg);
    }`
